# Let me compare the two approaches
input_test = [
    [1, 6, 2, 4, 1],
    [3, 9, 9, 9, 9],
    [9, 9, 3, 9, 9],
    [0, 2, 9, 5, 4],
    [7, 9, 9, 9, 9]
]

# 2x2 block expansion
def block_expansion(grid):
    n = len(grid)
    out = [[0]*(2*n) for _ in range(2*n)]
    for i in range(2*n):
        for j in range(2*n):
            out[i][j] = grid[i // 2][j // 2]
    return out

# Simple modulo tiling  
def modulo_tiling(grid):
    n = len(grid)
    out = [[0]*(2*n) for _ in range(2*n)]
    for i in range(2*n):
        for j in range(2*n):
            out[i][j] = grid[i % n][j % n]
    return out

be = block_expansion(input_test)
mt = modulo_tiling(input_test)

print("2x2 block expansion == modulo tiling:", be == mt)

print("\nDifferences:")
for i in range(10):
    for j in range(10):
        if be[i][j] != mt[i][j]:
            print(f"({i},{j}): BE={be[i][j]}, MT={mt[i][j]}, input[{i//2},{j//2}]={input_test[i//2][j//2]}")

