# Let me try: output[i][j] = input[j % 5][(i + j) % 5] or something like that
def pattern1(grid):
    N = len(grid)
    out = [[0]*(2*N) for _ in range(2*N)]
    for i in range(2*N):
        for j in range(2*N):
            out[i][j] = grid[j % N][(i + j) % 2*N]
    return out

def pattern2(grid):
    N = len(grid)
    out = [[0]*(2*N) for _ in range(2*N)]
    for i in range(2*N):
        for j in range(2*N):
            out[i][j] = grid[j % N][i % N]
    return out

def pattern3(grid):
    N = len(grid)
    out = [[0]*(2*N) for _ in range(2*N)]
    for i in range(2*N):
        for j in range(2*N):
            out[i][j] = grid[i % N][j % N]  # simple modulo tiling
    return out

def pattern4(grid):
    N = len(grid)
    out = [[0]*(2*N) for _ in range(2*N)]
    for i in range(2*N):
        for j in range(2*N):
            out[i][j] = grid[i % N][j % (2*N - j % N)]
    return out

def pattern5(grid):
    N = len(grid)
    out = [[0]*(2*N) for _ in range(2*N)]
    for i in range(2*N):
        for j in range(2*N):
            out[i][j] = grid[i % N][j % N]  # SAME as pattern 3
    return out

